mapper.select:
SELECT * FROM (
    SELECT fs.base_ym AS baseYm,
           pr.hazard_1m AS hazard1m,
           pr.hazard_2m AS hazard2m,
           pr.hazard_3m AS hazard3m
    FROM feature_snapshot fs
    JOIN prediction_result pr
        ON pr.prediction_id = (
            SELECT candidate.prediction_id
            FROM prediction_result candidate
            WHERE candidate.feature_snapshot_id = fs.feature_snapshot_id
              AND candidate.model_version = #{modelVersion}
            ORDER BY candidate.predicted_at DESC, candidate.prediction_id DESC
            LIMIT 1
        )
    WHERE fs.customer_id = #{customerId}
      AND fs.base_ym <= #{baseYm}
    ORDER BY fs.base_ym DESC
    LIMIT #{months}
) recent ORDER BY baseYm ASC
